namespace App\Http\Resources;

use Illuminate\Http\Request;
use Illuminate\Http\Resources\Json\JsonResource;

class WorkspaceUserResource extends JsonResource
{
    public function toArray(Request $request): array
    {
        $isSelf = $request->user()?->id === $this->id;

        return [
            'id' => $this->id,
            'name' => $this->name,
            'email' => $this->email,
            'sso_token_secret' => $this->when($isSelf, $this->sso_token_secret),
            'stripe_customer_id' => $this->when($isSelf || $request->user()?->isAdmin(), $this->stripe_customer_id),
            'mfa_recovery_codes' => $this->when($isSelf, $this->mfa_recovery_codes)
        ];
    }
}
